package com.careerguidance.controller;
import com.careerguidance.dto.request.*; import com.careerguidance.dto.response.*; import com.careerguidance.entity.User; import com.careerguidance.exception.UnauthorizedException; import com.careerguidance.repository.UserRepository; import com.careerguidance.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/mentor") public class MentorAuthController { private final AuthService auth;private final UserRepository users;private final PasswordEncoder passwords; public MentorAuthController(AuthService a,UserRepository u,PasswordEncoder p){auth=a;users=u;passwords=p;}
 @PostMapping("/login") public JwtResponse login(@Valid @RequestBody LoginRequest r){JwtResponse x=auth.login(r);if(!x.getRoles().contains("ROLE_MENTOR"))throw new UnauthorizedException("Mentor access required");return x;}
 @GetMapping("/profile") @org.springframework.security.access.prepost.PreAuthorize("hasRole('MENTOR')") public StudentSummaryResponse profile(Authentication a){User u=user(a);return new StudentSummaryResponse(u.getId(),u.getFirstName(),u.getLastName(),u.getEmail(),u.getCollegeName(),u.getCgpa(),u.getActive());}
 @PutMapping("/change-password") @org.springframework.security.access.prepost.PreAuthorize("hasRole('MENTOR')") public MessageResponse change(@Valid @RequestBody ChangePasswordRequest r,Authentication a){User u=user(a);if(!passwords.matches(r.getCurrentPassword(),u.getPassword()))throw new UnauthorizedException("Current password is incorrect");u.setPassword(passwords.encode(r.getNewPassword()));users.save(u);return new MessageResponse("Password changed successfully");}
 @PostMapping("/logout") @org.springframework.security.access.prepost.PreAuthorize("hasRole('MENTOR')") public MessageResponse logout(){return new MessageResponse("Logged out successfully; discard the JWT on the client");}
 private User user(Authentication a){return users.findByEmail(a.getName()).orElseThrow(()->new UnauthorizedException("User not found"));}}
